{ #"SYSTEM_SYSRULES_gridField_v1"( label: "", emptyGridMessage: "No recent activities found", data: ri!tasks, columns: { #"SYSTEM_SYSRULES_gridColumn"( label: "Task", align: "START", value: #"SYSTEM_SYSRULES_richTextDisplayField"( value: #"SYSTEM_SYSRULES_richTextItem_v1"( text: if( #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(fv!row.taskName), #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3197185", fv!row.taskName ) ) ) ), #"SYSTEM_SYSRULES_gridColumn"( label: "Assignee", sortField: "assignee", value: if( #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(fv!row.assignee), #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3197185", #"SYSTEM_SYSRULES_richTextDisplayField"( value: { #"SYSTEM_SYSRULES_richTextIcon"( icon: if( isusernametaken(fv!row.assignee), "user", "users" ), caption: if( isusernametaken(fv!row.assignee), "User", "Group" ), color: "ACCENT" ), #"SYSTEM_SYSRULES_richTextItem_v1"( text: concat( " ", if( isusernametaken(fv!row.assignee), #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3052910"(fv!row.assignee), fv!row.assignee ) ), link: #"SYSTEM_SYSRULES_userRecordLink"( user: fv!row.assignee, showWhen: isusernametaken(fv!row.assignee)
), linkStyle: "STANDALONE", style: "EMPHASIS" ) } ) ) ), #"SYSTEM_SYSRULES_gridColumn"( label: "Status", width: "NARROW_PLUS", sortField: "status", value: if( #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(fv!row.taskStatus), #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3197185", fv!row.taskStatus ) ), #"SYSTEM_SYSRULES_gridColumn"( label: "Module", sortField: "moduleName", align: "CENTER", value: fv!row.moduleName ), #"SYSTEM_SYSRULES_gridColumn"( label: "Last Modified By", sortField: "modifiedBy", value: if( length(split(fv!row.modifiedBy," ")) = 1, #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3052910"(user: fv!row.modifiedBy), fv!row.modifiedBy ) ), #"SYSTEM_SYSRULES_gridColumn"( label: "Modified Date", sortField: "modifiedOn", value: fv!row.modifiedOn ), #"SYSTEM_SYSRULES_gridColumn"( label: "Submitted By", sortField: "createdBy", value: if( length(split(fv!row.createdBy," ")) = 1, #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3052910"(user: fv!row.createdBy), fv!row.createdBy ) ), #"SYSTEM_SYSRULES_gridColumn"( label: "Submitted Date", sortField: "createdOn", value: fv!row.createdOn ) }, initialSorts:#"SYSTEM_SYSRULES_sortInfo"( field: "modifiedOn", ascending: false ), borderStyle: "LIGHT", shadeAlternateRows: true(), rowHeader: 1
